source=H/'nominate_field_ground_health_opening_r35.py';target=H/'diagnose_field_ground_health_opening_r36.py';assert not target.exists();text=source.read_text();a="   for _,inner,s,face in sorted(options,key=lambda x:x[:2]):";insert="   meeting=unary_union([region.intersection(f)for f in faces]);(out/(uid+'-'+str(radius)+'-legal-face-sites.wkb')).write_bytes(meeting.wkb);distances={l:meeting.distance(sources[l])if not meeting.is_empty and not sources[l].is_empty else None for l in sources};write(out/('distances-'+str(radius)+'.json'),{'ref':pad['ref'],'radius_mm':radius,'legal_outer_face_site_area_mm2':meeting.area,'source_distances_mm':distances,'options':[{'inner':l,'site_mm':[s.x,s.y],'source_annular_overlap_mm2':N.bounded_disk({'x':s.x,'y':s.y},.25).difference(N.bounded_disk({'x':s.x,'y':s.y},.1)).intersection(sources[l]).area,'region_covers':region.covers(s),'face_covers':f.covers(s)}for _,l,s,f in options]});print('R36_SOURCE_DISTANCE',pad['ref'],radius,'sites',meeting.area,'options',len(options),distances,flush=True)\n   continue\n";assert text.count(a)==1;text=text.replace(a,insert+a);compile(text,str(target),'exec');target.write_text(text);(H/'field-ground-health-r36-derivation.json').write_text(json.dumps({'source_sha256':sha(source),'derived_sha256':sha(target),'read_only_continue_before_all_via_track_trial_emission':True,'new_native_jobs':0},indent=1)+'\n')
